import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            B = []
            for k in range(N):
                B.append(int(next(iterator)))

            possible = False
            for i in range(N):
                if B[i] == i + 1:
                    possible = True
                    break

            if possible:
                results.append("YES")
            else:
                results.append("NO")

        except StopIteration:
            break

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
